code='''from itertools import permutations
from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v}
    frames = []
    frame_colors = set()
    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
        c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
        if r1-r0 < 2 or c1-c0 < 2:
            continue
        border = {(r0,c) for c in range(c0,c1+1)} | {(r1,c) for c in range(c0,c1+1)} | {(r,c0) for r in range(r0,r1+1)} | {(r,c1) for r in range(r0,r1+1)}
        if len(cells) == len(border) and set(cells) == border:
            frames.append((color,r0,r1,c0,c1))
            frame_colors.add(color)
    if not frames:
        return [row[:] for row in grid]
    markers = Counter(v for row in grid for v in row if v and v not in frame_colors)
    marker_colors = list(markers)
    capacities = [sum(1 for r in range(r0+1,r1) for c in range(c0+1,c1) if (r-r0-1+c-c0-1)%2 == 0) for _,r0,r1,c0,c1 in frames]
    best = min(permutations(marker_colors, len(frames)), key=lambda cs: sum(abs(markers[col]-cap) for col,cap in zip(cs,capacities)))
    out = [row[:] for row in grid]
    for (frame_color,r0,r1,c0,c1), fill in zip(frames,best):
        for r in range(r0+1,r1):
            for c in range(c0+1,c1):
                if (r-r0-1+c-c0-1)%2 == 0:
                    out[r][c] = fill
    for r in range(h):
        for c in range(w):
            if grid[r][c] and grid[r][c] not in frame_colors:
                out[r][c] = 0
    return out
'''
